012345 

B. 
542342 

C. 
542241 

D. 
142245 

E. 
542151 

int size = 6; 
int[] st1 = {9, 16, 0, 1, 25, 4}; 
int[] st2 = new int[size]; 
for(int i = 0; i < size; i++) 
    st2[i] = (int)Math.sqrt( st1[i] ); 
int[] st3 = new int[size]; 
for(int i = 0; i < size; i++){ 
    st3[ st2[i] ]++; 
    st3[ st1[i] % size ]++; 
    st3[ st1[i] / size ]++; 
} 
for(int i : st3 ) 
    System.out.print(i);

