int lim = 4;
char[][] tab = new char[lim][lim];
String[] nms = {"lars", "kime", "jake",
"ashe"};
for(int i = lim - 1; i >= 0; i--)
  for(int j = 0; j < lim; j++)
    tab[i][j] = nms[j].charAt(lim - i - 1);

for(char[] row : tab)
  for( char c : row )
    System.out.print(c);

